INSERT INTO ict_demo.service_owners(owner_code,owner_label) VALUES('DEMO-ICT-OWN-A','Synthetic Service Operations'),('DEMO-ICT-OWN-B','Synthetic Business Applications') ON CONFLICT(owner_code) DO NOTHING;
INSERT INTO ict_demo.services(service_code,service_name,service_tier,owner_id,status,support_hours) SELECT v.code,v.name,v.tier,o.owner_id,v.status,'demo_support' FROM (VALUES('DEMO-SVC-001','Synthetic Records Service','high','DEMO-ICT-OWN-A','active'),('DEMO-SVC-002','Synthetic Public Information Service','standard','DEMO-ICT-OWN-B','degraded'),('DEMO-SVC-003','Synthetic Reporting Service','standard','DEMO-ICT-OWN-A','planned')) v(code,name,tier,owner,status) JOIN ict_demo.service_owners o ON o.owner_code=v.owner ON CONFLICT(service_code) DO NOTHING;
INSERT INTO ict_demo.assets(asset_ref,service_id,asset_type,environment,sensitivity,lifecycle) SELECT v.ref,s.service_id,v.typ,v.env,v.sensitivity,v.life FROM (VALUES('DEMO-ASSET-001','DEMO-SVC-001','database','staging','internal','active'),('DEMO-ASSET-002','DEMO-SVC-002','software','production','public_metadata','maintenance'),('DEMO-ASSET-003','DEMO-SVC-003','server','development','internal','planned')) v(ref,svc,typ,env,sensitivity,life) JOIN ict_demo.services s ON s.service_code=v.svc ON CONFLICT(asset_ref) DO NOTHING;
INSERT INTO ict_demo.work_items(item_ref,service_id,item_type,summary,priority,status,due_at,owner_ref) SELECT v.ref,s.service_id,v.typ,v.summary,v.priority,v.status,v.due,'DEMO-OWNER' FROM (VALUES('DEMO-WORK-001','DEMO-SVC-002','incident','Synthetic availability review',2,'in_progress',now()+INTERVAL '1 day'),('DEMO-WORK-002','DEMO-SVC-001','maintenance','Synthetic database maintenance',3,'open',now()+INTERVAL '7 days'),('DEMO-WORK-003','DEMO-SVC-003','change','Synthetic service rollout planning',4,'blocked',now()+INTERVAL '10 days')) v(ref,svc,typ,summary,priority,status,due) JOIN ict_demo.services s ON s.service_code=v.svc ON CONFLICT(item_ref) DO NOTHING;